"""Prebuilt General/texture archives use generated bytes and private game/profile folders."""
import gzip
import hashlib
import json
import os
from pathlib import Path
import struct
import sys
import tempfile
import unittest
from unittest.mock import patch

from ba2_fixture import general_archive, texture_archive

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts" / "game"))
sys.path.insert(0, str(ROOT / "scripts"))
sys.path.insert(0, str(ROOT / "src"))
import exp_install as exp  # noqa: E402
from fo4sf.ba2 import _dds_header_dx10  # noqa: E402
from fo4sf.workshop import piece_icons  # noqa: E402
import verify_packed_experiment as vpe  # noqa: E402


def _legacy_dds(fourcc: bytes, payload: bytes, width: int = 4, height: int = 4) -> bytes:
    """Build a 128-byte legacy (non-DX10) DDS file with the given FourCC (e.g. b'DXT1' or b'DXT5')."""
    flags = 0x1 | 0x2 | 0x4 | 0x1000
    caps = 0x1000
    hdr = b"DDS " + struct.pack("<7I", 124, flags, height, width, 0, 0, 1) + b"\0" * 44
    hdr += struct.pack("<II4sIIIII", 32, 0x4, fourcc, 0, 0, 0, 0, 0)
    hdr += struct.pack("<5I", caps, 0, 0, 0, 0)
    assert len(hdr) == 128
    return hdr + payload


def _as_dx10_dds(raw: bytes) -> bytes:
    """Wrap a legacy DXT1/DXT5 DDS pixel payload in a 148-byte DX10 DDS header for ba2_fixture.texture_archive."""
    if raw[84:88] == b"DX10":
        return raw
    height, width, mips = struct.unpack_from("<I", raw, 12)[0], struct.unpack_from("<I", raw, 16)[0], max(struct.unpack_from("<I", raw, 28)[0], 1)
    dxgi = {b"DXT1": 71, b"DXT5": 77}.get(raw[84:88], 77)
    return _dds_header_dx10(width, height, mips, dxgi, False) + raw[128:]


class PrepackedTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.stage = self.root / "stage"
        self.data = self.root / "game" / "Data"
        self.plugins = self.root / "local" / "Starfield" / "Plugins.txt"
        self.data.mkdir(parents=True)
        self.plugins.parent.mkdir(parents=True)
        self.original = b"\xef\xbb\xbf# owner\r\n*FO4Port.esm\r\n"
        self.plugins.write_bytes(self.original)
        self.resources = {"Terrain/World.btd": b"synthetic terrain"}
        self.textures = {"Textures/FO4SF/icon.dds": piece_icons.dds(1, "synthetic")}
        for name, content in {**self.resources, **self.textures}.items():
            path = self.stage / "Data" / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
        (self.stage / "Experiment.esm").write_bytes(b"synthetic plugin")
        # The selected Main archive may live outside the stage and use another basename.
        self.main = self.root / "prebuilt" / "selected.ba2"
        self.main.parent.mkdir()
        self.main.write_bytes(general_archive(self.resources))
        self.texture = self.main.with_name("Experiment - Textures.ba2")
        self.texture.write_bytes(texture_archive(self.textures))
        self.argv = ["install", "--exp-dir", str(self.stage), "--starfield", str(self.data.parent),
                     "--pack", "--prepacked", str(self.main), "--textures-archive"]
        environment = patch.dict(os.environ, {"LOCALAPPDATA": str(self.plugins.parent.parent)})
        environment.start()
        self.addCleanup(environment.stop)

    def snapshot(self, root):
        return {p.relative_to(root).as_posix(): p.read_bytes() for p in root.rglob("*") if p.is_file()}

    def install_without_building(self):
        with patch.object(exp, "build_ba2", side_effect=AssertionError("prepacked must never build")) as build, \
                patch.object(exp.subprocess, "run", side_effect=AssertionError("no external tools")) as process:
            try:
                exp.main(self.argv)
            finally:
                build.assert_not_called()
                process.assert_not_called()

    def assert_refused(self, reason="archive"):
        before = self.snapshot(self.root)
        with self.assertRaisesRegex(SystemExit, reason):
            self.install_without_building()
        self.assertEqual(self.snapshot(self.root), before)
        self.assertFalse((self.data / exp.RECORD).exists())

    def test_combined_prebuilt_archives_install_relaunch_remove_without_build(self):
        owner = self.data / "FO4Port.deploy.json"
        owner.write_bytes(b'{"files": [], "complete": true}')
        before = self.snapshot(self.root)
        self.install_without_building()
        record = (self.data / exp.RECORD).read_bytes()
        receipt = json.loads(record)
        self.assertTrue(receipt["complete"])
        self.assertEqual(set(receipt["files"]),
                         {"Experiment.esm", "Experiment - Main.ba2", "Experiment - Textures.ba2"})
        self.assertEqual(set(receipt["source_inputs"]),
                         {"plugin/Experiment.esm", "Data/Terrain/World.btd", "Data/Textures/FO4SF/icon.dds"})
        self.assertEqual((self.data / "Experiment - Main.ba2").read_bytes(), self.main.read_bytes())
        self.assertEqual((self.data / "Experiment - Textures.ba2").read_bytes(), self.texture.read_bytes())
        self.assertFalse((self.data / "Textures").exists())
        self.assertEqual(self.plugins.read_bytes(), self.original + b"*Experiment.esm\r\n")
        self.install_without_building()
        self.assertEqual((self.data / exp.RECORD).read_bytes(), record)
        exp.main(["uninstall", "--starfield", str(self.data.parent)])
        after = self.snapshot(self.root)
        history = [name for name in after if name not in before]
        self.assertEqual(len(history), 1)
        self.assertTrue(history[0].startswith("local/FO4SF/experiment-receipts/"))
        self.assertEqual(json.loads(gzip.decompress(after.pop(history[0]))), {**receipt, "cleanup_pending": True})
        self.assertEqual(after, before)

    def test_missing_main_or_texture_archive_never_builds(self):
        for path in (self.main, self.texture):
            with self.subTest(path=path.name):
                content = path.read_bytes()
                path.unlink()
                self.assert_refused()
                path.write_bytes(content)

    def test_wrong_texture_archive_refuses_before_publication(self):
        wrong = dict(self.textures)
        wrong[next(iter(wrong))] = piece_icons.dds(2, "different")
        for payload in (general_archive(self.textures), texture_archive(wrong), texture_archive({}),
                        texture_archive({"Textures/other.dds": next(iter(self.textures.values()))}), b"BTDX"):
            with self.subTest(payload=payload[:24]):
                self.texture.write_bytes(payload)
                self.assert_refused()

    def test_general_archive_must_cover_exactly_the_nontexture_inputs(self):
        for payload in (general_archive({**self.resources, **self.textures}), general_archive({}),
                        general_archive({"Terrain/World.btd": b"wrong"}), texture_archive(self.textures)):
            with self.subTest(payload=payload[:24]):
                self.main.write_bytes(payload)
                self.assert_refused()

    def test_default_keeps_textures_in_general_prebuilt_archive(self):
        self.argv.remove("--textures-archive")
        self.main.write_bytes(general_archive({**self.resources, **self.textures}))
        self.texture.unlink()
        self.install_without_building()
        receipt = json.loads((self.data / exp.RECORD).read_bytes())
        self.assertEqual(set(receipt["files"]), {"Experiment.esm", "Experiment - Main.ba2"})

    def test_texture_mode_without_texture_inputs_needs_only_main(self):
        (self.stage / "Data" / next(iter(self.textures))).unlink()
        (self.stage / "Data" / "Textures" / "FO4SF").rmdir()
        (self.stage / "Data" / "Textures").rmdir()
        self.texture.unlink()
        self.install_without_building()
        receipt = json.loads((self.data / exp.RECORD).read_bytes())
        self.assertEqual(set(receipt["files"]), {"Experiment.esm", "Experiment - Main.ba2"})

    def test_prepacked_still_requires_pack(self):
        self.argv.remove("--pack")
        self.assert_refused("requires --pack")

    def test_textures_archive_handles_lowercase_textures_folder_and_legacy_dds(self):
        """I8: lowercase Data/textures/... routes to Textures.ba2 and legacy DXT1/DXT5 DDS verifies by pixel payload."""
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            stage = root / "stage"
            data = root / "game" / "Data"
            plugins = root / "local" / "Starfield" / "Plugins.txt"
            stage.mkdir(parents=True, exist_ok=True)
            data.mkdir(parents=True)
            plugins.parent.mkdir(parents=True)
            plugins.write_bytes(b"\xef\xbb\xbf# owner\r\n*FO4Port.esm\r\n")
            (stage / "Experiment.esm").write_bytes(b"synthetic plugin")
            (stage / "Data" / "meshes" / "prop.nif").parent.mkdir(parents=True, exist_ok=True)
            (stage / "Data" / "meshes" / "prop.nif").write_bytes(b"nif-bytes")
            dxt5_payload = b"\xAA\xBB\xCC\xDD" * 4
            dxt1_payload = b"\x11\x22\x33\x44" * 2
            dxt5_dds = _legacy_dds(b"DXT5", dxt5_payload)
            dxt1_dds = _legacy_dds(b"DXT1", dxt1_payload)
            (stage / "Data" / "textures" / "weapons").mkdir(parents=True, exist_ok=True)
            (stage / "Data" / "textures" / "weapons" / "pistol_d.dds").write_bytes(dxt5_dds)
            (stage / "Data" / "textures" / "weapons" / "pistol_n.dds").write_bytes(dxt1_dds)

            seen_calls: list[tuple[list[str], str]] = []

            def fake_build_archive(ns, out_path, folders, fmt, compression="None"):
                seen_calls.append((list(folders), fmt))
                collected = {}
                for folder in folders:
                    folder_root = Path(ns.staging) / folder
                    for p in sorted(folder_root.rglob("*")):
                        if p.is_file():
                            rel = p.relative_to(ns.staging).as_posix()
                            raw = p.read_bytes()
                            collected[rel] = _as_dx10_dds(raw) if fmt == "DDS" else raw
                raw = texture_archive(collected) if fmt == "DDS" else general_archive(collected)
                Path(out_path).write_bytes(raw)

            with patch.dict(os.environ, {"LOCALAPPDATA": str(plugins.parent.parent)}), \
                    patch.object(exp.deployment, "build_archive", side_effect=fake_build_archive):
                exp.main([
                    "install", "--exp-dir", str(stage), "--starfield", str(data.parent),
                    "--pack", "--textures-archive",
                ])
                # Relaunch and uninstall also succeed cleanly
                exp.main([
                    "install", "--exp-dir", str(stage), "--starfield", str(data.parent),
                    "--pack", "--textures-archive",
                ])
                self.assertEqual(seen_calls, [(["meshes"], "General"), (["textures"], "DDS")])
                receipt = json.loads((data / exp.RECORD).read_text(encoding="utf-8"))
                self.assertEqual(
                    set(receipt["files"]),
                    {"Experiment.esm", "Experiment - Main.ba2", "Experiment - Textures.ba2"},
                )
                exp.main(["uninstall", "--starfield", str(data.parent)])

    def test_verify_texture_archive_compares_legacy_dds_pixel_payload(self):
        """I8: legacy DXT1/DXT5 DDS differs from regenerated DX10 header in full SHA-256, but matches pixel payload."""
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            dxt1 = _legacy_dds(b"DXT1", b"DXT1PIXELS" * 8)
            dxt5 = _legacy_dds(b"DXT5", b"DXT5PIXELS" * 16)
            files = {
                "textures/a.dds": dxt1,
                "textures/b.dds": dxt5,
            }
            for rel, content in files.items():
                p = root / "Data" / rel
                p.parent.mkdir(parents=True, exist_ok=True)
                p.write_bytes(content)
            ba2_path = root / "tex.ba2"
            ba2_path.write_bytes(texture_archive({k: _as_dx10_dds(v) for k, v in files.items()}))
            inputs = {"Data/" + rel: hashlib.sha256(content).hexdigest() for rel, content in files.items()}
            # Full-file SHA-256 differs because ba2.read() regenerates a 148-byte DX10 header
            from fo4sf.ba2 import Ba2
            arc = Ba2(str(ba2_path))
            self.assertNotEqual(hashlib.sha256(arc.read("textures/a.dds")).hexdigest(), inputs["Data/textures/a.dds"])
            # Pixel-payload verification succeeds
            vpe.verify_texture_archive(str(ba2_path), inputs, source_root=root)

            # Mutated pixel payload is rejected
            bad_files = {**files, "textures/b.dds": _legacy_dds(b"DXT5", b"CORRUPT!!!" * 16)}
            ba2_path.write_bytes(texture_archive({k: _as_dx10_dds(v) for k, v in bad_files.items()}))
            with self.assertRaisesRegex(ValueError, "differs from pinned input"):
                vpe.verify_texture_archive(str(ba2_path), inputs, source_root=root)

            # Non-DDS input file is rejected
            (root / "Data" / "textures" / "a.dds").write_bytes(b"NOT_A_DDS_FILE" + b"\0" * 128)
            bad_inputs = {**inputs, "Data/textures/a.dds": hashlib.sha256((root / "Data" / "textures" / "a.dds").read_bytes()).hexdigest()}
            ba2_path.write_bytes(texture_archive({k: _as_dx10_dds(v) for k, v in files.items()}))
            with self.assertRaisesRegex(ValueError, "not a valid DDS"):
                vpe.verify_texture_archive(str(ba2_path), bad_inputs, source_root=root)
